"""One current report answering the lab assignment; preserved evidence only, no model calls."""
import json
from pathlib import Path
from pypdf import PdfReader
from report_utils import render_report

ROOT=Path(__file__).resolve().parents[1]


def read(path):
    return json.loads((ROOT/path).read_text(encoding='utf-8'))


def main():
    summary=read('artifacts/analysis/deliberation_summary_2026-11-25.json')
    usage=read('artifacts/analysis/deliberation_usage_2026-11-25.json')
    verification=read('artifacts/setup/deliberation_validation_2026-11-25.json')
    studies=summary['studies']
    bonsai=next(s for s in studies if s['backend']=='bonsai' and s['runs'])
    luna=next(s for s in studies if s['backend']=='codex' and s['runs'])
    base_b=next(r for r in bonsai['runs'] if r['config']['name']=='rotating_text')
    base_l=luna['runs'][0]
    diagnostics={s['backend']:s['diagnostics'] for s in studies if not s['runs']}
    api_calls=usage['historical_bonsai_http_calls']+usage['new_bonsai_http_calls']
    api_tokens=usage['historical_bonsai_total_tokens']+sum(usage['bonsai_new_usage'][k] for k in ('input_tokens','output_tokens'))
    cli_tokens=sum(usage['codex_new_usage_including_probe'][k] for k in ('input_tokens','output_tokens'))
    num=lambda x:f'{x:,}'.replace(',',' ')
    pages=[]
    def page(title):
        p=[('h1',title)];pages.append(p);return p
    def para(p,text):p.append(('p',text))
    def heading(p,text):p.append(('h2',text))
    def table(p,headers,rows,widths):p.append(('table',(headers,rows,widths)))

    p=page('Итоговый отчет по прототипу коллективных предпочтений')
    para(p,'Отчет по заданию лабораторной. Работы выполнены 21-25 ноября 2026 года. Состояние на 25.11.2026. Документ объединяет оба протокола и предназначен для обсуждения результатов и дальнейших этапов с коллегами.')
    heading(p,'Главный результат')
    para(p,'Мы собрали работающий минимальный прототип первой идеи: изменение индивидуальных и коллективных предпочтений под влиянием внешних сведений, общения и памяти. Использован Concordia 2.4.0. Подключены bonsai2-27b через OpenAI-совместимый API и GPT-6-Luna через Codex. Техническая реализуемость небольшого контролируемого сценария подтверждена. Качество агентного поведения и перенос результатов на реальные сообщества требуют дальнейшей проверки.')
    heading(p,'Что удалось сделать по заданию')
    para(p,'1. Выбрали небольшой сценарий: шесть вымышленных участников обсуждают цифровой доступ и печатные книги в библиотеке. Провели контрольные и реальные LLM-эксперименты, сохранили конфигурации, наблюдения, промпты, ответы и расход.')
    para(p,'2. Разобрали устройство используемых компонентов Concordia: агент, память наблюдений, сборка контекста и вызов модели. Среду, граф контактов и расписание раундов реализовали самостоятельно. Их границы описаны в этом отчете.')
    para(p,'3. Проверили чувствительность к профилям, новостям, памяти, исходной позиции и смене собеседников. Обнаружили слабую динамику, повторение аргументов и противоречия в рассуждениях даже при верном извлечении фактов.')
    para(p,'4. Выделили решения для своей системы: компонентный агент, явная доставка событий, разделение хранения и извлечения памяти, единый интерфейс моделей и воспроизводимый протокол. Сформировали следующие этапы с проверяемыми результатами.')
    heading(p,'Текущий объем проверки')
    table(p,['Материал','Подтвержденный объем'],[
        ['Численный контроль','40 основных запусков, две длинные пробы памяти; новый протокол также проверен с заглушкой'],
        ['bonsai через API',f'{num(api_calls)} HTTP-вызовов, {num(api_tokens)} токенов за все этапы'],
        ['Luna через Codex',f"{usage['new_codex_cli_invocations']} CLI-вызовов, {num(cli_tokens)} токенов по usage"],
        ['Проверки',f"{verification['unit_tests_passed']} автоматических тестов; автономная демонстрация на двух размерах экрана"]
    ],[.30,.70])
    para(p,'В объем включены неудачные пробы и повторная диагностика. CLI-вызовы и HTTP-запросы учитываются раздельно. Денежная стоимость неизвестна; вход Codex содержит служебный контекст. Для подготовки этого отчета новых обращений к моделям не делали.')

    p=page('Сценарий и проведенные эксперименты')
    heading(p,'Почему выбран такой сценарий')
    para(p,'Библиотечный выбор позволяет задать понятные альтернативы, разные потребности и несколько проверяемых фактов. Позиция представляется числом от -1 (печатные книги) до +1 (цифровой доступ), дополненным публичным аргументом. Масштаб из шести участников позволяет вручную просматривать ответы и ограничивать число обращений к LLM. Мы моделируем вымышленную ситуацию, данные о настоящих людях не используются.')
    heading(p,'Первый протокол')
    para(p,'Шесть ролей, четыре раунда, кольцо контактов, одна новость в первом раунде. Сопоставлены отсутствие воздействий, только новость, только общение и их сочетание. Численные исходные профили проверены на трех наборах; отдельно исследованы окно наблюдений и предъявление собственного initial_opinion. Точные повторы проверяли воспроизводимость одной конфигурации. Этот сценарий выявил быстрый выход на почти неизменные позиции и бедную аргументацию.')
    heading(p,'Второй протокол')
    para(p,'Профили стали конкретнее: у студента, родителя, библиотекаря, учителя, пенсионера и разработчика есть потребности и бюджеты. В раунде 0 модель формирует исходную позицию. Далее идут пять раундов с новыми собеседниками: каждый встречается с каждым другим ровно один раз. Одновременно в отдельном условии проверяются постоянные пары. Собственная история аргументов возвращается в контекст.')
    table(p,['Раунд','Новое официальное сведение внутри сценария'],[
        ['0','Цифровая стоимость 120, печатная 80; цифровые книги требуют интернета'],
        ['1','Появляется чтение загруженных цифровых книг без интернета'],
        ['2','Фасад перекрашен; стоимость и условия выбора не меняются'],
        ['3','Бюллетень сообщает новую цифровую стоимость 40'],
        ['4','Исправление: правильная цифровая стоимость 140, прежние 40 отозваны'],
        ['5','Появляются обучение работе с устройствами и выдача устройств']
    ],[.12,.88])
    para(p,'Для bonsai выполнены пять условий: основной сценарий, постоянные пары, отсутствие своей истории, добавление чисел собеседника и профили только с названиями ролей. Для Luna выполнен основной сценарий. У обоих маршрутов есть одношаговая диагностика без новости, с существенным фактом, с нерелевантным фактом и с исправлением стоимости. Вторая модель пока не прошла весь набор отдельных условий.')

    p=page('Агенты память среда и взаимодействия в Concordia')
    para(p,'Concordia выбрали, поскольку ее компоненты позволили отдельно собрать память, контекст и модель для небольшого контролируемого сценария. Сравнительный запуск AgentSociety 2 и OASIS не проводился; превосходство Concordia над ними не установлено.')
    heading(p,'Агенты и принятие решения')
    para(p,'Используются настоящие EntityAgent из Concordia. Агент объединяет компоненты, которые участвуют в наблюдении и действии. Наш компонент DecisionContext в первом протоколе и DiscussionContext во втором хранит профиль, номер раунда и текущую позицию, а перед действием собирает предметный контекст. ConcatActComponent передает его модели через интерфейс LanguageModel. ActionSpec задает запрашиваемый формат действия. Ответ проверяется перед изменением состояния.')
    heading(p,'Память и извлечение сведений')
    para(p,'ListMemory хранит записи, ObservationToMemory записывает полученные наблюдения. В первом протоколе в промпт извлекались внешние сведения за один или четыре раунда; более длинное окно не удаляло старую историю из хранилища. Собственных прошлых аргументов тогда не было. Во втором протоколе сохраняются также собственные ответы: позиция, аргумент, объяснение и указанные факты.')
    para(p,'В текущий контекст второго протокола попадают официальные записи, последнее публичное сообщение выбранного партнера и, если условие это разрешает, собственная история. Более старые сообщения прежних партнеров хранятся, но напрямую не извлекаются. Разделение хранения и извлечения позволяет менять доступную память как параметр эксперимента.')
    heading(p,'Среда и расписание')
    para(p,'Предметная среда написана в проекте: она задает события, участников, контакты, номера раундов и метрики. Стандартный движок Game Master в опытах не использовался. Поэтому выполненная работа показывает применение агентных компонентов Concordia и нашей среды; полноценное сравнение готовых сред трех фреймворков не проводилось.')
    heading(p,'Взаимодействия и порядок действий')
    para(p,'Перед действиями агенты получают новые сведения среды и адресованные им сообщения партнеров из снимка предыдущего раунда. Затем агенты отвечают, а новые позиции фиксируются вместе. Последний вызванный агент не получает доступа к еще не опубликованным решениям того же раунда. Во втором протоколе три непересекающиеся пары меняются по турнирному расписанию. Встреча означает один синхронный обмен публичными позициями; многошагового диалога внутри пары пока нет.')
    heading(p,'Подключение моделей')
    para(p,'Для bonsai реализован адаптер OpenAI-совместимого API с журналом вызовов и лимитами. Для Luna реализован CodexModel с тем же интерфейсом LanguageModel: запускается отдельный codex exec в режиме ephemeral и read-only со схемой ответа. Отдельный новый API-ключ не потребовался. Codex использует действующий вход и его лимиты; его системный контекст и параметры отличаются от прямого API.')

    p=page('Что удалось проверить и какие результаты получены')
    heading(p,'Работоспособность и воспроизводимость')
    para(p,'Агенты получают адресованные им наблюдения, собирают контекст и возвращают проверяемые действия. Тестами проверены численный контроль, порядок действий, доставка по сети, ограничения частоты запросов, восстановление состояния первого протокола и расписание встреч без повторов. Всего проходят 36 тестов. Сохранены исходные ответы, частичные результаты, снимки кода и контрольные суммы. Автономная демонстрация показывает реальные записи без новых запросов.')
    heading(p,'Первый протокол показал слабую устойчивость результатов')
    para(p,'Четыре повторные траектории и 96 текстов ответов совпали с исходным пилотом. При других численных профилях эффект общения изменил направление: разность итоговой дисперсии с контролем составила +0,0176, -0,0227 и -0,0331. В базовых условиях с воздействием после первого раунда неизменными были 143 из 162 шагов отдельных агентов (88,3%). Это зависимые наблюдения одного стенда, а не независимая выборка людей.')
    heading(p,'Проверка фактов и проверка аргументов дают разные результаты')
    table(p,['Показатель второго протокола','bonsai API','Luna Codex'],[
        ['Верные наборы фактов в исправленной диагностике',f"{diagnostics['bonsai']['beliefs_correct']}/24",f"{diagnostics['codex']['beliefs_correct']}/24"],
        ['Верные наборы фактов в основном сценарии',f"{base_b['beliefs_correct']}/36",f"{base_l['beliefs_correct']}/36"],
        ['Неизменные позиции после первого раунда',f"{base_b['late_unchanged_opinions']}/24",f"{base_l['late_unchanged_opinions']}/24"],
        ['Дословные повторы своего предыдущего сообщения',str(base_b['verbatim_own_repeats']),str(base_l['verbatim_own_repeats'])]
    ],[.62,.19,.19])
    para(p,'Проверяются три явных факта: офлайн-доступ и две стоимости. У bonsai при верных полях фактов текст называл 80 более дешевой стоимостью, чем 40, и относил 120 к бюджету 100. В просмотренных репликах Luna студент учитывал бюджет: печатный вариант при цифровой стоимости 120, цифровой при 40, возврат после исправления до 140. Это выбранные проверенные примеры; независимой разметки всех аргументов пока нет.')
    heading(p,'Память и смена собеседников')
    para(p,'У bonsai численные траектории с новыми парами, постоянными парами и добавленными числами партнеров совпали. Без собственной истории в третьем раунде дополнительно сменили сторону пенсионер и библиотекарь. При профилях из одного названия роли все шесть участников оставались на -1. Это показывает чувствительность одной конфигурации к контексту. Общая польза памяти и влияние общения на реальные сообщества не установлены.')

    p=page('Полезные решения и основные сложности')
    heading(p,'Что стоит использовать в своей системе или библиотеке')
    para(p,'Компонентную сборку агента: профиль и состояние, память, извлечение контекста и выбор действия можно менять отдельно. Единый интерфейс модели позволяет переключать численный контроль, HTTP API и Codex, сохраняя общий цикл агента. Это удобно для проверки инфраструктуры до расходования LLM-доступа.')
    para(p,'Явный формат событий с источником и временем, раздельные хранение и извлечение памяти, адресную доставку и синхронные фазы раунда. Благодаря этому можно контролировать, кто что видел, и сравнивать память или сеть, сохраняя остальные параметры.')
    para(p,'Экспериментальный слой: конфигурации условий, сохранение точных запросов и ответов, проверку схемы и диапазонов, учет токенов, ограничение запросов и промежуточные сохранения. Неудачные ответы тоже должны оставаться в данных. Эти решения полезны независимо от выбора Concordia.')
    heading(p,'Чего не хватает в текущем прототипе')
    para(p,'Нет надежной оценки смысла аргументов: валидный JSON и правильные фактические поля пропускают противоречия в объяснении. Нужны разметка бюджета и сравнений, проверка персональных обстоятельств, учет исправлений и различение цитаты и собственной позиции.')
    para(p,'Собственная история теперь есть, но нет проверенной политики ее сжатия и исправления ошибок. Более длинная память может закреплять неверный довод. Расписание контактов меняется, однако агенты не выбирают партнеров самостоятельно. Не реализованы многошаговый диалог в паре, динамическое доверие и отдельная память отношений. Это ограничения нашей реализации; они не означают отсутствия соответствующих возможностей во всем Concordia.')
    heading(p,'Что оказалось сложным')
    table(p,['Область','Оценка сложности','Наблюдение'],[
        ['Подключение и версии','2-3 из 5','Потребовалась настройка API компонентов и моделей'],
        ['Память и сопоставимость','3 из 5','Извлечение и своя история меняют содержание контекста'],
        ['Смена пар','2 из 5','Реализованы и проверены 15 уникальных пар'],
        ['Оценка смысла','4 из 5','Извлечение факта не гарантирует верного рассуждения']
    ],[.29,.24,.47])
    para(p,'Оценки инженерные, человеко-часы не измерялись. Возникали ограничения установки, различия API, лимиты шлюза и рост контекста. Первый новый smoke остановился на слишком длинном объяснении; ответ сохранен. Ранняя одношаговая диагностика имела несогласованный номер раунда и отдельно повторена для обоих маршрутов с общей отметкой времени.')

    p=page('Ограничения и следующие этапы')
    heading(p,'Как можно интерпретировать текущий результат')
    para(p,'Задание на минимальный прототип выполнено: выбран сценарий, использован фреймворк, подключены модели, проведены эксперименты и выявлены сложности. Научная новизна и соответствие поведению людей не подтверждались. В новом протоколе проверена одна перестановка профилей, фиксированный порядок событий и один сценарий. Сравнение Luna и bonsai относится к разным маршрутам с разным системным контекстом и настройками генерации. Изменение мнения не является обязательным признаком качества.')
    heading(p,'Этап 1 Задать критерии качества аргументации')
    para(p,'Подготовить рубрику: неверное сравнение стоимости, нарушение бюджета, неподтвержденные личные обстоятельства, игнорирование исправления, повтор аргумента. Независимо разметить общую выборку ответов обоих маршрутов. Результат этапа - таблица ошибок с цитатами и долями по заранее определенным категориям, а не оценка только по валидности JSON.')
    heading(p,'Этап 2 Проверить устойчивость и сравнение моделей')
    para(p,'Повторить несколько перестановок профилей и генераций, менять порядок событий отдельным фактором. Для более чистого сравнения моделей выровнять API, системную инструкцию, схему и параметры; если это недоступно, сохранять явное разделение маршрутов. Результат - диапазоны эффектов и оценка вариации, включая повторные базовые ответы без новости.')
    heading(p,'Этап 3 Отделить влияние общения от фактов среды')
    para(p,'Сопоставить новые пары, постоянные пары, отсутствие сообщений и перемешанные сообщения при одинаковых официальных фактах. Проверять изменения аргументов и позиций. При необходимости добавить несколько реплик внутри встречи. Результат - понимание, влияет ли содержание собеседника на решение, а не только смена события или собственная история.')
    heading(p,'Этап 4 Улучшить память и выделить библиотечные компоненты')
    para(p,'Сравнить полную собственную историю, краткое резюме и память с явным отзывом ошибочных фактов. Затем выделить интерфейсы профиля, события, хранилища, извлечения, планировщика контактов, модели и оценщика. Результат - повторный запуск того же эксперимента с заменой одного компонента и без изменения предметного сценария.')
    heading(p,'После инженерных проверок')
    para(p,'Если результаты устойчивы, выбрать независимый сценарий и данные для проверки социальной правдоподобности. Такой этап потребует отдельного дизайна валидации; нынешние синтетические опыты его не заменяют.')
    heading(p,'Материалы для обсуждения и воспроизведения')
